use super::*;
#[test]
fn original_repin_alternative_preserves_all_ranks_and_returns_every_partial_row(){
 let f:serde_json::Value=serde_json::from_str(include_str!("repin-alternative.json")).unwrap();let source:Alternative=semio_framework_pack_json::from_json_str(&f["alternative"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();
 for append in [false,true]{for wide in [false,true]{let mut source=source.clone();let mut old=f["checkpointId"].as_str().unwrap().to_string();if wide{old="λ-common-prefix".repeat(8197);source.name="wide-name-λ".repeat(8197);source.checkpoint_ids[1]=old.clone();source.checkpoint_ids[3]=old.clone();}let input=OriginalAlternativeInput{generation:41,alternative:&source,checkpoint_id:if append{None}else{Some(&old)},replacement:f["replacement"].as_str().unwrap()};
  for cut in f["cuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){let mut owner=OriginalAlternativeBirth::default();for index in 0..100000{if cut==Some(index)||owner.ready(){break}let d=owner.demands(&input).unwrap();assert!(d.copy_bytes<=4096);let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in 0..5{let mut denied=g;let amount=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if amount==0{continue}match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_capacity_bytes-=1,3=>denied.maximum_release_bytes-=1,_=>denied.maximum_depth-=1}let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,denied).unwrap());assert_eq!(p,Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,g).unwrap());assert!(p.fits(g));assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(index<99999);}
   if cut.is_none(){let value=owner.prepared().unwrap();if append{assert_eq!(value.id,source.id);assert_eq!(value.name,source.name);assert_eq!(&value.checkpoint_ids[..source.checkpoint_ids.len()],&source.checkpoint_ids);assert_eq!(value.checkpoint_ids.last().unwrap(),input.replacement);if !wide{let actual:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(value)).unwrap();assert_eq!(actual,f["expectedAppend"]);}}else if wide{assert_eq!(value.name,source.name);assert_eq!(value.checkpoint_ids[1],input.replacement);assert_eq!(value.checkpoint_ids[3],input.replacement);assert_eq!(value.checkpoint_ids[0],source.checkpoint_ids[0]);assert_eq!(value.checkpoint_ids[2],source.checkpoint_ids[2]);}else{let actual:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(value)).unwrap();assert_eq!(actual,f["expected"]);}}
   while !owner.terminal_is_empty(){let d=owner.close_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!((h.requested_bytes,h.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
  }
 }
}
}
